#include<bits/stdc++.h>

using namespace std;

typedef long long LL;


int main (){
    ios::sync_with_stdio(false);
    std::cin.tie(0);
    int n; cin >> n;
    vector<int> cost(n);
    for(int & i : cost) cin >> i;
    queue<int> q;
    q.push(0);
    LL s = cost[0];
    for(int i = 1; i < n - 1; i ++)
    {
    	while(q.size() && cost[q.front()] + i - q.front() >= cost[i]) // 如果从当前 i 买物资比之前更划算了
    		q.pop(); // 直接删去之前的即可
    	q.push(i);
    	s += cost[q.front()] + i - q.front(); // 最划算的一个
    }
    cout << s << "\n";
    return 0;
}

```

